Method.Implementation:
#dim tSourceFilename,tFilename,tCopyFileName As %String =""
#dim tSC As %Status=$$$OK
Set tFilename=..Adapter.CreateTimestamp("",..Filename)
Set tSourceFilename=..Adapter.fixPath(..Adapter.FilePath)_tFilename
set tCopyFileName=..Adapter.CreateTimestamp("",..CopyFilename)
set tCopyFileName=..Adapter.fixPath(..Adapter.FilePath)_tCopyFileName
set pResponse=##class(Ens.StringResponse).%New()
do {
	If (##class(%File).Exists(tCopyFileName)){ 
		set tSC=$$$ERROR($$$GeneralError,tCopyFileName_" Exists, Kindly look to see why file did not get Sent. ")
		quit
	}
	If (##class(%File).Exists(tSourceFilename)) {
		set tSC=##class(%File).Rename(tSourceFilename,tCopyFileName)
	}
} while(0)
if tSC{
	set pResponse.StringValue=tSourceFilename_" to "_tCopyFileName_" COPY FILE -SUCCESS"
}else { set pResponse.StringValue= $System.Status.GetOneErrorText(tSC)_" - COPY FAILED"
}
quit $$$OK

Try {
	do {
		set tStatus = $$$OK
		set tStatus=##super()
	    If $$$ISERR(tStatus) Quit
		Set tFilePath=..Adapter.fixPath(..Adapter.FilePath)
		// Check if Directory is present if not create
		 If (##class(%File).DirectoryExists(tFilePath)=0) {
			set tStatus=##class(%File).CreateDirectoryChain(tFilePath)
			$$$TRACE( " Directrory Create Status "_tStatus)
			if (tStatus=0){
				set tStatus=$$$ERROR($$$GeneralError," Failed to Create Directory "_tFilePath)
				quit
			}
		}
	}while(0)
}
Catch ex {
	Set tStatus = $$$EnsSystemError
}
Quit tStatus
